import { NextResponse } from "next/server";

export type CategoryNode = {
  id: number;
  name: string;
  children?: CategoryNode[];
};

export async function GET() {
  try {
    const baseUrl =
      process.env.CATALOG_BASE_URL ?? process.env.BACKEND_BASE_URL;

    const res = await fetch(`${baseUrl}/category/tree`, {
      // luôn lấy fresh để form create/edit dùng đúng dữ liệu mới nhất
      cache: "no-store",
    });

    if (!res.ok) {
      console.error("Error calling catalog /category/tree:", res.status, res.statusText);
      return NextResponse.json<CategoryNode[]>([], { status: 200 });
    }

    const data = (await res.json()) as CategoryNode[] | null;
    return NextResponse.json<CategoryNode[]>(data ?? []);
  } catch (error) {
    console.error("Failed to proxy category tree to catalog", error);
    // fallback: trả mảng rỗng nhưng có thể hiển thị message phía client
    return NextResponse.json<CategoryNode[]>([], { status: 200 });
  }
}
